import { mkdirSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { eq } from 'drizzle-orm';
import { drizzle } from 'drizzle-orm/node-sqlite';
import { migrate } from 'drizzle-orm/node-sqlite/migrator';
import type { ClassDoc, ClassState } from '../types.ts';
import { classes } from './schema.ts';

/** Generated by `npm run db:generate`; resolved from the working directory like `data/` and `bank/`. */
const MIGRATIONS_DIR = join(process.cwd(), 'drizzle');

/** Classes saved before courses existed were all GCSE Physics. */
export const LEGACY_COURSE_ID = 'aqa-gcse-physics';

export interface Store {
	get(code: string): ClassDoc | null;
	/** Insert a new class. Returns false if the code is already taken. */
	create(code: string, doc: ClassDoc): boolean;
	/** Overwrite an existing class document. Returns false if the code is unknown. */
	save(code: string, doc: ClassDoc): boolean;
}

interface LegacyClassState {
	lesson: number;
	skills: Record<string, { taughtAt: number }>;
	lastUsed: Record<string, number>;
}

/** Class states saved before per-question scheduling held one schedule per skill: keep the ticks, restart every question unpractised. */
function upgradeState(state: ClassState | LegacyClassState): ClassState {
	if (!('skills' in state)) return state;
	return {
		lesson: state.lesson,
		taught: Object.fromEntries(Object.entries(state.skills).map(([id, s]) => [id, s.taughtAt])),
		questions: {},
		lastUsed: state.lastUsed
	};
}

/** A class's whole state is one JSON document keyed by its code. */
export function createStore(path: string): Store {
	if (path !== ':memory:') mkdirSync(dirname(path), { recursive: true });
	const db = drizzle(path);
	migrate(db, { migrationsFolder: MIGRATIONS_DIR });
	return {
		get(code) {
			const row = db.select({ doc: classes.doc }).from(classes).where(eq(classes.code, code)).get();
			if (!row) return null;
			const doc = JSON.parse(row.doc) as Omit<ClassDoc, 'state' | 'course'> & {
				course?: string;
				state: ClassState | LegacyClassState;
			};
			return { course: LEGACY_COURSE_ID, ...doc, state: upgradeState(doc.state) };
		},
		create(code, doc) {
			const res = db
				.insert(classes)
				.values({ code, doc: JSON.stringify(doc), updatedAt: Date.now() })
				.onConflictDoNothing()
				.run();
			return Number(res.changes) === 1;
		},
		save(code, doc) {
			const res = db
				.update(classes)
				.set({ doc: JSON.stringify(doc), updatedAt: Date.now() })
				.where(eq(classes.code, code))
				.run();
			return Number(res.changes) === 1;
		}
	};
}
